internal object AgentsListAgentSessionEventsOperation {
    /**
     * Streams live events for an agent session. See session events.
     *
     * @param sessionId The ID of the session.
     */
    fun listAgentSessionEvents(
        clientConfig: ClientConfig,
        sessionId: String,
        options: RequestOptions? = null,
    ): Sequence<SessionEvent> {
        return sequence {
            for (_ev in
                SdkClient.stream(
                    SdkClient.RequestSpec(
                        "GET",
                        "/agents/sessions/${SdkClient.encodePathSegment(sessionId)}/events",
                        config = clientConfig,
                        operationId = "listAgentSessionEvents",
                        streamFormat = "sse",
                        streamMediaType = "text/event-stream",
                        chunkDomain = "bytes",
                        options = options,
                        errors =
                            mapOf(
                                "400" to ErrorResponse2::class.java,
                                "401" to ErrorResponse2::class.java,
                                "403" to ErrorResponse2::class.java,
                                "404" to ErrorResponse2::class.java,
                                "409" to ErrorResponse2::class.java,
                                "500" to ErrorResponse2::class.java,
                                "503" to ErrorResponse2::class.java,
                            ),
                    )
                )) {
                if (_ev.data == "[DONE]") return@sequence
                yield(
                    try {
                        SdkClient.mapper.readValue(_ev.data, SessionEvent::class.java)
                    } catch (error: com.fasterxml.jackson.core.JsonProcessingException) {
                        SdkClient.rethrowEventDecode(error, _ev.data)
                    }
                )
            }
        }
    }
}

internal object AgentsCreateAgentSessionEventsOperation {
    /**
     * Submits message, cancellation, tool-result, or computer-use approval-response events to a
     * managed agent session. Cancellation can recover a still-open turn whose backend execution has
     * ended by marking it cancelled and abandoning unpublished outputs. Saved results, published
     * files, and existing terminal outcomes are preserved. HTTP 202 confirms acceptance, not
     * durable completion. See session events.
     *
     * @param sessionId The ID of the session.
     * @param events The input events to submit to the session.
     * @param idempotencyKey An optional client-generated key that makes retries of submitted
     *   messages idempotent.
     */
    fun createAgentSessionEvents(
        clientConfig: ClientConfig,
        sessionId: String,
        events: List<SessionInputParam>,
        idempotencyKey: String? = null,
        options: RequestOptions? = null,
    ): Unit {
        Validation.validateLength(
            "session_id",
            sessionId,
            Validation.LengthOpts(min = 0, max = 1048576),
        )

        Validation.validateItems("events", events, Validation.LengthOpts(min = 0, max = 16384))

        if (idempotencyKey != null) {
            Validation.validateLength(
                "Idempotency-Key",
                idempotencyKey,
                Validation.LengthOpts(min = 1, max = 256),
            )
        }

        SdkClient.request<Unit>(
            SdkClient.RequestSpec(
                "POST",
                "/agents/sessions/${SdkClient.encodePathSegment(sessionId)}/events",
                config = clientConfig,
                body = SdkClient.bodyMap("events" to (events)),
                operationId = "createAgentSessionEvents",
                decoder = SdkClient.ResponseDecoder.EMPTY,
                extraHeaders =
                    SdkClient.headers(
                        "Idempotency-Key" to SdkClient.headerValue(idempotencyKey, false)
                    ),
                options = options,
                errors =
                    mapOf(
                        "400" to ErrorResponse2::class.java,
                        "401" to ErrorResponse2::class.java,
                        "403" to ErrorResponse2::class.java,
                        "404" to ErrorResponse2::class.java,
                        "409" to ErrorResponse2::class.java,
                        "500" to ErrorResponse2::class.java,
                        "503" to ErrorResponse2::class.java,
                    ),
            )
        )
    }
}

